# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.models import Span
from hourglass.gaps import OutsideHoursError, uncovered_labels


def _spans(*texts):
    return [parse_span(text) for text in texts]


class UncoveredLabelTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        self.assertEqual(
            uncovered_labels(_spans("09:00-12:00", "13:00-17:00"), parse_span("09:00-17:00")),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        self.assertEqual(
            uncovered_labels(_spans("10:00-11:00"), parse_span("09:00-12:00")),
            ["gap 09:00-10:00 (60 min)", "gap 11:00-12:00 (60 min)"]
        )

    def test_nobody_worked(self):
        self.assertEqual(
            uncovered_labels([], parse_span("09:00-09:30")),
            ["gap 09:00-09:30 (30 min)"]
        )

    def test_full_coverage_has_no_gaps(self):
        self.assertEqual(
            uncovered_labels(_spans("09:00-13:00", "13:00-17:00"), parse_span("09:00-17:00")),
            []
        )

    def test_overlapping_and_unsorted_spans(self):
        self.assertEqual(
            uncovered_labels(_spans("14:00-16:00", "09:00-11:00", "10:00-12:00"), parse_span("09:00-16:00")),
            ["gap 12:00-14:00 (120 min)"]
        )

    def test_span_outside_opening_hours_raises(self):
        with self.assertRaises(OutsideHoursError):
            uncovered_labels(_spans("08:00-10:00"), parse_span("09:00-17:00"))
        with self.assertRaises(OutsideHoursError):
            uncovered_labels([Span(600, 1100)], parse_span("09:00-17:00"))

    def test_error_is_a_value_error(self):
        self.assertTrue(issubclass(OutsideHoursError, ValueError))


if __name__ == "__main__":
    unittest.main()
